from app import stats_plots


def test_contour_count():
    assert stats_plots.contour_count(3) == 5


def test_box_medians():
    medians = stats_plots.box_medians({"a": [1, 2, 3], "b": [4, 6, 8]})
    assert medians == {"a": 2.0, "b": 6.0}

